export const ASSUMPTIONS_BIAS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu asumsi",q:"Sebuah 'asumsi' adalah...",options:["sesuatu yang kita anggap benar tanpa memeriksanya lebih dulu","sesuatu yang kita lihat sendiri & sudah dibuktikan dengan data","kesimpulan akhir yang disetujui oleh seluruh anggota kelompok"],answer:0,explain:"Asumsi adalah hal yang kita terima begitu saja sebagai benar. Kadang tepat, kadang keliru — & sering tak kita sadari.",hint:"Dianggap benar tanpa dicek."},
{n:2,type:"mcq",micro:"Asumsi tersembunyi",q:"'Ayo kita main sepak bola di lapangan sepulang sekolah.' Asumsi tersembunyi di kalimat ini:",options:["lapangan sedang kosong, & semua yang diajak gemar bermain sepak bola setiap hari","lapangan akan kosong & cuacanya memungkinkan, & semua yang diajak bisa ikut","guru yang mengizinkan & wasitnya sudah menunggu di tengah lapangan"],answer:1,explain:"Banyak rencana punya asumsi yang tak diucapkan. Menyadarinya membantu kita menyiapkan rencana cadangan.",hint:"Apa yang dianggap 'pasti beres' padahal belum tentu?"},
{n:3,type:"tf",micro:"Asumsi baik & buruk",q:"Benar atau Salah: Semua asumsi itu buruk & harus selalu dihindari.",answer:false,explain:"Kita tidak bisa memeriksa segalanya; sebagian asumsi wajar (mis. 'matahari akan terbit besok'). Yang penting adalah menyadari asumsi kita & memeriksa yang berisiko.",hint:"Sebagian asumsi wajar; yang berisiko perlu dicek."},
{n:4,type:"mcq",micro:"Sudut pandang",q:"'Sudut pandang' (perspektif) adalah...",options:["pendapat akhir yang benar bagi siapa saja yang mendengarnya","sebuah fakta yang wajib dipercaya oleh orang yang mendengarnya","posisi & pengalaman dari mana seseorang melihat sebuah situasi"],answer:2,explain:"Orang yang berbeda posisi, pengalaman, & kepentingan sering melihat kejadian yang sama secara berbeda.",hint:"Dari mana seseorang 'berdiri' saat melihat."},
{n:5,type:"mcq",micro:"Peristiwa sama, pandangan beda",q:"Bel istirahat berbunyi lebih awal. Bagi murid yang sedang lapar itu kabar baik; bagi murid yang hampir menyelesaikan tugas kelompok itu mengganggu. Ini menunjukkan...",options:["peristiwa yang sama bisa terasa & dinilai berbeda tergantung situasi & kebutuhan tiap orang","peristiwa yang sama dirasakan orang lain dengan cara serupa, jadi beda penilaian muncul dari salah paham","hanya ada satu cara yang benar memandang peristiwa seperti itu, sedangkan cara lain keliru atau mengada-ada"],answer:0,explain:"Menyadari bahwa orang lain punya sudut pandang berbeda adalah dasar empati & berpikir adil.",hint:"Kebutuhan berbeda → penilaian berbeda."},
{n:6,type:"mcq",micro:"Menanyakan asumsi diri",q:"Pertanyaan yang membantu menemukan asumsimu sendiri:",options:["'Siapa yang paling banyak menyetujui pendapatku di kelas?'","'Apa yang aku anggap pasti benar di sini, padahal belum kuperiksa?'","'Apakah pendapatku sudah cukup bagus untuk dibagikan ke orang lain?'"],answer:1,explain:"Menyadari asumsi dimulai dengan sengaja bertanya apa yang kita terima begitu saja.",hint:"Apa yang kuanggap 'sudah jelas'?"},
{n:7,type:"tf",micro:"Asumsi dalam instruksi",q:"Benar atau Salah: Kalau sebuah instruksi terasa membingungkan, itu selalu semata-mata karena si penerima kurang pintar, bukan karena asumsi si pemberi instruksi.",answer:false,explain:"Sebaliknya, sering penyebabnya adalah asumsi si pemberi instruksi tentang apa yang 'sudah pasti kita tahu'. Hal yang jelas baginya belum tentu jelas bagi kita; bertanya menutup celah itu.",hint:"Ia menganggap kita sudah tahu sesuatu."},
{n:8,type:"mcq",micro:"Apa itu bias",q:"Dalam berpikir, 'bias' adalah...",options:["kesalahan hitung yang terjadi bila kita lupa menjumlahkan angka dengan teliti saat mengerjakan soal yang panjang di kelas","kebiasaan memilih teman yang sama di setiap kegiatan yang dilakukan di kelas, merasa nyaman dengan mereka saja","kecenderungan berpikir yang bisa membuat penilaian kita miring dari yang seharusnya, sering tanpa kita sadari"],answer:2,explain:"Bias adalah 'jalan pintas' berpikir yang kadang menyesatkan. Semua orang memilikinya; yang bisa kita lakukan adalah mengenalinya.",hint:"Kemiringan penilaian yang sering tak disadari."},
{n:9,type:"mcq",micro:"Bias 'ingin percaya'",q:"Kamu berharap timmu menang, lalu hanya mengingat momen bagus timmu & melupakan kesalahannya. Ini contoh...",options:["bias: kita cenderung memperhatikan hal yang mendukung harapan kita","kebiasaan baik: kita mengingat semua kejadian dengan adil","sikap objektif: kita menimbang hal baik dan buruk secara berimbang"],answer:0,explain:"Bias konfirmasi: kita menyaring informasi agar cocok dengan apa yang ingin kita percaya.",hint:"Mengingat yang cocok, melupakan yang tidak."},
{n:10,type:"tf",micro:"Semua orang punya bias",q:"Benar atau Salah: Hanya orang yang tidak pintar yang punya bias berpikir; orang cerdas sudah bebas dari bias.",answer:false,explain:"Sebaliknya, bias adalah bagian dari cara kerja pikiran semua orang, termasuk yang cerdas. Kepintaran justru kadang membuat orang lebih pandai membela biasnya.",hint:"Semua orang, tanpa kecuali."},
{n:11,type:"open",micro:"Asumsi di rencanamu",q:"Pikirkan satu rencana kecilmu minggu ini (mis. mengerjakan proyek, pergi ke suatu tempat). Tuliskan dua asumsi yang kamu buat & apa yang bisa kamu cek untuk memastikannya.",explain:"Menyadari & memeriksa asumsi mengubah rencana yang rapuh menjadi rencana yang siap.",hint:"2 asumsi + cara mengeceknya.",sample:"Rencana: mengerjakan tugas kelompok di rumah temanku Sabtu pagi. Asumsi: (1) temanku ada di rumah & setuju waktunya — bisa kucek dengan bertanya langsung malam ini; (2) kami akan punya bahan yang dibutuhkan (kertas, lem, laptop) — bisa kucek dengan membuat daftar & memastikan siapa membawa apa."},
{n:12,type:"mcq",micro:"Sudut pandang yang hilang",q:"Kelas merancang lomba lari untuk semua murid, tapi tidak memikirkan teman yang memakai kursi roda. Yang terlewat:",options:["waktu pelaksanaan lomba yang bentrok dengan jadwal ujian & pelajaran lain di sekolah pada minggu itu","sudut pandang murid dengan kebutuhan berbeda — perlu lomba yang bisa diikuti semua orang","jumlah hadiah lomba & warna garis start yang dipakai untuk lomba lari itu"],answer:1,explain:"Rencana yang adil mempertimbangkan sudut pandang semua orang yang terdampak, terutama yang mudah terlupakan.",hint:"Siapa yang tidak bisa ikut dengan rencana ini?"},
{n:13,type:"mcq",micro:"Kesan pertama",q:"Kamu langsung menganggap anak baru yang berpakaian rapi 'pasti pintar & rajin'. Ini contoh...",options:["fakta yang sudah terbukti: orang berpakaian rapi memang pintar dan rajin dalam belajar","penilaian yang adil, memakai ciri yang terlihat sebagai bukti kecerdasan seseorang","bias kesan pertama: satu sifat yang terlihat membuat kita menduga sifat-sifat lain tanpa bukti"],answer:2,explain:"Efek halo: satu kesan baik (atau buruk) mewarnai penilaian kita atas hal-hal lain yang belum kita ketahui.",hint:"Satu sifat terlihat → menebak sifat lain."},
{n:14,type:"tf",micro:"Perasaan kuat sebagai sinyal",q:"Benar atau Salah: Saat kita merasakan emosi yang sangat kuat tentang sebuah topik, itu tanda baik untuk melambat & memeriksa apakah penilaian kita masih adil.",answer:true,explain:"Emosi kuat bisa mempersempit pandangan & memperbesar bias. Menyadarinya adalah isyarat untuk berhati-hati, bukan berhenti berpikir.",hint:"Emosi tinggi = perlu ekstra hati-hati."},
{n:15,type:"mcq",micro:"Asumsi dalam pertanyaan",q:"Pertanyaan 'Kenapa kamu selalu lupa tugas?' mengandung asumsi bahwa...",options:["orang itu memang 'selalu' lupa — padahal mungkin hanya sekali atau dua kali","tugas itu sengaja diberikan guru untuk menguji ingatan orang yang ditanya","orang yang bertanya itu benar-benar peduli & ingin membantu menyelesaikan tugas"],answer:0,explain:"Sebagian pertanyaan menyelipkan asumsi yang belum tentu benar. Menyadarinya membuat kita bisa meluruskan dulu ('sebenarnya baru kali ini').",hint:"Kata 'selalu' menyembunyikan klaim yang belum dicek."},
{n:16,type:"mcq",micro:"Melihat dari kursi orang lain",q:"Cara paling langsung memahami sudut pandang orang lain:",options:["menebak-nebak apa yang mereka pikirkan dari wajah & cara berjalan mereka","bertanya & mendengarkan bagaimana mereka melihat situasinya, tanpa buru-buru membantah","membayangkan dirimu sendiri di posisi mereka lalu menganggap perasaanmu sama"],answer:1,explain:"Kita sering keliru menebak isi pikiran orang. Bertanya & mendengarkan adalah jalan tercepat & paling menghormati.",hint:"Tanya, jangan tebak."},
{n:17,type:"order",micro:"Memeriksa sebuah asumsi",q:"Urutkan langkah memeriksa asumsi sebelum bertindak:",items:["Sadari pernyataan/rencana ini bertumpu pada sesuatu yang belum dicek","Nyatakan asumsinya dengan jelas ('aku menganggap bahwa...')","Nilai: seberapa besar risikonya bila asumsi ini salah?","Untuk asumsi berisiko, cari cara memeriksanya sebelum melanjutkan"],answer:[0,1,2,3],explain:"Sadari → nyatakan → nilai risiko → periksa yang berisiko.",hint:"Menyadari lebih dulu, memeriksa terakhir."},
{n:18,type:"mcq",micro:"Bias 'mereka semua sama'",q:"'Anak kelas sebelah semuanya nakal' adalah contoh...",options:["bias memilih contoh yang paling jelas lalu menganggapnya mewakili setiap anak di kelas lain","fakta yang sudah terbukti, kamu melihat sendiri beberapa anak kelas sebelah yang nakal di kantin saat jam istirahat","bias menggeneralisasi sekelompok orang dari beberapa contoh, mengabaikan bahwa tiap orang berbeda"],answer:2,explain:"Menganggap satu kelompok seragam ('mereka semua begitu') mengabaikan keberagaman di dalamnya & mudah menjadi tidak adil.",hint:"'Semua' dari sekelompok orang — hati-hati."},
{n:19,type:"tf",micro:"Bias & niat buruk",q:"Benar atau Salah: Seseorang bisa memiliki bias dalam penilaiannya meskipun ia tidak berniat jahat sama sekali.",answer:true,explain:"Bias sering bekerja diam-diam. Orang baik pun bisa menilai tidak adil tanpa sadar — karena itu memeriksanya penting.",hint:"Bias tak butuh niat buruk."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Tiga hal yang membuat penilaian kita bisa meleset:",options:["asumsi yang tak diperiksa, hanya melihat dari satu sudut pandang, & bias berpikir yang tak disadari","kurang tidur, terlalu banyak membaca, & terlalu cepat berbicara dengan teman-teman sekelas","bukti yang terlalu banyak, penjelasan yang terlalu rinci, & terlalu banyak teman yang membantu mengerjakan tugas"],answer:0,explain:"Menyadari asumsi, mencari sudut pandang lain, & mengenali bias adalah tiga penjaga utama berpikir yang adil & akurat.",hint:"Asumsi, sudut pandang, bias."},
{n:21,type:"classify",micro:"Dinyatakan atau diasumsikan",q:"Seseorang berkata: 'Kita harus berangkat jam 6 supaya tidak terlambat ke acara jam 8.' Kelompokkan:",items:["Acara mulai jam 8","Perjalanan memakan waktu sekitar 2 jam","Tidak akan ada hambatan besar di jalan","Berangkat lebih pagi lebih aman"],groups:["Dinyatakan langsung","Diasumsikan (tidak diucapkan)"],answer:{"Dinyatakan langsung":["Acara mulai jam 8","Berangkat lebih pagi lebih aman"],"Diasumsikan (tidak diucapkan)":["Perjalanan memakan waktu sekitar 2 jam","Tidak akan ada hambatan besar di jalan"]},explain:"Rencana yang terdengar sederhana sering bertumpu pada asumsi tak terucap tentang waktu tempuh & kelancaran.",hint:"Mana yang benar-benar diucapkan?"},
{n:22,type:"mcq",micro:"Menemukan asumsi dalam klaim",q:"'Kita tidak perlu membawa jas hujan, kan sekarang musim kemarau.' Asumsinya:",options:["jas hujan itu berat dan merepotkan jika dibawa ke sekolah setiap hari","musim kemarau berarti pasti tidak akan hujan sama sekali hari ini","teman-teman lain juga tidak membawa jas hujan pada hari-hari sebelumnya"],answer:1,explain:"Klaim ini bertumpu pada asumsi bahwa 'musim kemarau = tidak mungkin hujan', padahal hujan sesekali tetap bisa terjadi.",hint:"Apa yang dianggap mustahil di sini?"},
{n:23,type:"mcq",micro:"Sudut pandang yang hilang dalam keputusan",q:"OSIS memutuskan jam kegiatan klub tanpa menanyakan anggota yang tinggal jauh & pulang naik jemputan. Sudut pandang yang terlewat:",options:["pendapat pembina tentang warna seragam klub di sekolah","usulan anggota tentang nama klub & jadwal rapat tahunan","anggota yang punya kendala transportasi & waktu pulang"],answer:2,explain:"Keputusan yang adil menanyakan orang yang paling terdampak, bukan hanya yang paling mudah dihubungi.",hint:"Siapa yang paling sulit mengikuti keputusan ini?"},
{n:24,type:"mcq",micro:"Asumsi dalam lelucon/sindiran",q:"Kenapa sebuah lelucon bisa terasa menyakitkan bagi sebagian orang tapi tidak bagi yang lain?",options:["karena lelucon sering bertumpu pada asumsi atau anggapan tentang suatu kelompok yang tidak dirasakan sama oleh semua pendengar","karena lelucon dimaksudkan untuk menyakiti orang yang berbeda dari kita & seluruh pendengar merasakannya dengan cara sama persis","karena orang yang tersinggung terlalu sensitif & tak punya selera humor seperti kebanyakan orang lain di sekitarnya"],answer:0,explain:"Memahami bahwa orang berangkat dari pengalaman berbeda membantu kita berhati-hati dengan candaan yang menyinggung kelompok tertentu.",hint:"Anggapan tentang kelompok yang tidak semua orang rasakan sama."},
{n:25,type:"tf",micro:"Mengecek lebih baik dari menebak",q:"Benar atau Salah: Meski sebuah asumsi mudah diperiksa hanya dengan satu pesan singkat, tetap lebih baik berjalan dengan tebakan saja.",answer:false,explain:"Sebaliknya, asumsi yang murah dicek sebaiknya selalu dicek. Menebak baru masuk akal bila memeriksanya benar-benar tidak mungkin.",hint:"Murah dicek = cek saja."},
{n:26,type:"mcq",micro:"Bias kelompok (kami vs mereka)",q:"Dalam pertandingan antar kelas, kamu menilai pelanggaran oleh kelasmu 'tidak sengaja' tapi pelanggaran serupa oleh kelas lawan 'curang'. Ini contoh...",options:["penilaian objektif: aturan yang sama diterapkan pada semua tim","bias memihak kelompok sendiri: standar yang berbeda untuk 'kami' & 'mereka'","kebiasaan membaca aturan pertandingan lebih dulu sebelum bertanding"],answer:1,explain:"Kita cenderung memaafkan kelompok sendiri & menghakimi kelompok lain untuk hal yang sama. Menyadarinya membantu menilai lebih adil.",hint:"Standar berbeda untuk pihak sendiri & pihak lawan."},
{n:27,type:"mcq",micro:"Asumsi dalam iklan",q:"Iklan: 'Anak hebat memilih sepatu X.' Asumsi yang ingin ditanamkan:",options:["anak yang memakai sepatu X otomatis hebat, & anak hebat dipilih lewat sepatunya","sepatu X adalah sepatu terbaik di dunia & terbukti lebih baik dari sepatu merek lain","kalau kamu tidak memilih sepatu X, kamu kurang hebat — sebuah anggapan yang tidak berdasar"],answer:2,explain:"Iklan sering menyelipkan asumsi tentang identitas ('anak hebat = pemakai produk ini') agar kita merasa perlu membeli.",hint:"Apa yang ingin kamu percayai tentang dirimu?"},
{n:28,type:"open",micro:"Dua sudut pandang",q:"Pilih satu kejadian kecil yang pernah kamu alami di sekolah (mis. antrean kantin yang ricuh). Tuliskan bagaimana kejadian itu mungkin terlihat dari dua sudut pandang berbeda.",explain:"Berlatih membayangkan sudut pandang lain mengurangi kesalahpahaman & penilaian tergesa.",hint:"Kejadian + sisi kamu + sisi orang lain.",sample:"Kejadian: seorang anak menyerobot antrean kantin. Sudut pandangku (yang mengantre lama): ia tidak sopan & tidak menghargai orang lain. Sudut pandang anak itu (mungkin): ia hanya menitip pesan ke temannya yang sudah di depan, atau ia terburu-buru karena dipanggil guru & tidak sempat menjelaskan. Melihat dua sisi membuatku tidak langsung marah & mau bertanya dulu."},
{n:29,type:"mcq",micro:"Bias ikut-ikutan",q:"Seluruh grup memilih ide A, dan kamu ikut memilih A meski diam-diam berpikir ide B lebih baik, hanya karena tidak enak berbeda. Ini contoh...",options:["bias ikut-ikutan: mengikuti mayoritas tanpa menimbang sendiri","kepemimpinan: kamu berani memimpin kelompok menuju satu ide","kerja sama yang baik; semua anggota kelompok akhirnya menyepakati satu pilihan"],answer:0,explain:"Tekanan kelompok bisa membuat kita menekan penilaian sendiri. Kelompok yang sehat justru menghargai pandangan berbeda yang disampaikan dengan sopan.",hint:"Ikut mayoritas walau tak yakin."},
{n:30,type:"order",micro:"Menemukan sudut pandang yang hilang",q:"Urutkan langkah memastikan sebuah rencana kelas adil bagi semua:",items:["Daftar semua orang yang akan terdampak rencana ini","Untuk tiap kelompok, tanyakan 'bagaimana rencana ini terasa dari posisi mereka?'","Cari suara yang belum terdengar & tanyakan langsung","Sesuaikan rencana agar bisa diikuti oleh sebanyak mungkin orang"],answer:[0,1,2,3],explain:"Daftar yang terdampak → bayangkan tiap sudut pandang → tanyakan yang belum terdengar → sesuaikan.",hint:"Daftar dulu siapa saja yang terdampak."},
{n:31,type:"mcq",micro:"Asumsi tentang alasan orang",q:"Temanmu tidak membalas pesanmu seharian. Kamu berasumsi 'dia sengaja mengabaikanku'. Asumsi lain yang sama masuk akal:",options:["dia sedang marah padamu & tidak ingin berbicara lagi denganmu mulai hari ini sampai kamu minta maaf","ponselnya mati, dia sibuk, tidak melihat notifikasi, atau sedang tidak boleh memegang ponsel","dia sudah membalas semua pesanmu, tetapi pesannya tidak sampai ke ponselmu yang sedang bermasalah"],answer:1,explain:"Kita cenderung berasumsi tindakan orang lain ditujukan pada kita. Sering ada penjelasan yang lebih sederhana & tidak personal.",hint:"Penjelasan yang tidak berpusat pada dirimu."},
{n:32,type:"tf",micro:"Menyalahkan orang, bukan situasi",q:"Benar atau Salah: Saat seseorang berbuat kesalahan, kita cenderung cepat menyimpulkan itu karena sifat buruknya, & kurang mempertimbangkan situasi yang menekannya.",answer:true,explain:"Ini bias yang umum: untuk orang lain kita menyalahkan wataknya; untuk diri sendiri kita menyalahkan keadaan. Menyeimbangkannya membuat penilaian lebih adil.",hint:"Untuk orang lain: 'dia memang begitu'. Untuk diri: 'keadaannya sulit'."},
{n:33,type:"mcq",micro:"Asumsi dalam soal cerita",q:"Soal: 'Ani punya 3 apel, Budi memberinya beberapa lagi, kini Ani punya 7. Berapa yang Budi berikan?' Asumsi yang wajar & memang dimaksudkan:",options:["apel yang dimaksud adalah apel merah yang manis dari kebun nenek","Ani & Budi berteman dekat, dan Budi memberi apel dengan senang hati","tidak ada apel yang dimakan atau hilang di antara kedua waktu itu"],answer:2,explain:"Soal matematika mengandalkan asumsi yang disepakati (tidak ada yang hilang). Dalam kehidupan nyata, asumsi seperti itu justru perlu dicek.",hint:"Apa yang dianggap 'tidak berubah' di antara dua keadaan?"},
{n:34,type:"mcq",micro:"Bias karena mudah diingat",q:"Setelah menonton berita tentang satu kecelakaan sepeda, kamu tiba-tiba merasa 'bersepeda sangat berbahaya'. Yang terjadi:",options:["satu kejadian yang mudah & jelas diingat membuatnya terasa lebih sering & lebih besar daripada sebenarnya","bias ketersediaan membuatmu menganggap bersepeda aman, banyak orang bersepeda tanpa kecelakaan","kamu mendapat informasi lengkap tentang jumlah kecelakaan sepeda sehingga penilaianmu menjadi tepat"],answer:0,explain:"Kejadian yang dramatis & baru saja kita dengar terasa lebih 'mungkin' padahal belum tentu. Data yang lebih luas memberi gambaran yang lebih tepat.",hint:"Mudah diingat ≠ sering terjadi."},
{n:35,type:"mcq",micro:"Memeriksa asumsi bersama",q:"Sebelum kelompokmu mulai proyek, cara baik menangani asumsi:",options:["langsung mulai mengerjakan tanpa membahas apa-apa; anggota yang rajin biasanya tahu apa yang harus dilakukan dalam proyek itu nanti","luangkan beberapa menit untuk menuliskan 'kita berasumsi bahwa...' dan cek mana yang perlu dipastikan (tenggat, alat, tugas)","cukup menunjuk satu ketua yang akan menentukan seluruh asumsi sendiri & tidak perlu didiskusikan dengan anggota lain"],answer:1,explain:"Menyamakan asumsi di awal mencegah salah paham besar di tengah jalan.",hint:"Tulis & sepakati asumsi bersama dulu."},
{n:36,type:"open",micro:"Bias pada dirimu",q:"Tuliskan satu situasi di mana kamu menyadari (saat itu atau belakangan) bahwa penilaianmu terhadap seseorang atau sesuatu dipengaruhi bias — mis. kesan pertama, memihak teman, atau ingin percaya sesuatu. Apa yang membantumu menyadarinya?",explain:"Mengakui bias sendiri adalah tanda kekuatan berpikir, bukan kelemahan. Itu langkah pertama untuk menilai lebih adil.",hint:"Situasi + jenis bias + apa yang menyadarkanmu.",sample:"Aku pernah yakin seorang teman baruku pelit karena di hari pertama ia tidak mau berbagi bekal. Belakangan aku tahu ia sedang menjalani pantangan makanan tertentu & sebenarnya sering membantu orang lain dengan cara lain. Yang membantuku menyadari adalah melihat lebih banyak contoh perilakunya, bukan hanya menggantung pada kesan pertama."},
{n:37,type:"mcq",micro:"Sudut pandang penulis",q:"Saat membaca sebuah artikel, menyadari 'siapa yang menulis ini & dari posisi apa' membantu karena...",options:["judul artikel dibuat editor untuk meringkas isi, jadi cukup membaca judul tanpa menelaah isinya","penulis hanya menulis hal yang ia lihat sendiri, dan tulisannya bebas dari kepentingan & pandangan pribadi, jadi tidak perlu dibandingkan","setiap penulis punya sudut pandang & kepentingan yang bisa memengaruhi fakta mana yang ditonjolkan atau dihilangkan"],answer:2,explain:"Tidak ada tulisan yang benar-benar 'tanpa sudut pandang'. Mengetahui posisi penulis membantu kita membaca lebih kritis, bukan menolak mentah-mentah.",hint:"Dari posisi apa ini ditulis?"},
{n:38,type:"tf",micro:"Sudut pandang berbeda, sama-sama jujur",q:"Benar atau Salah: Jika dua orang menceritakan kejadian yang sama dengan berbeda, pasti salah satu di antara mereka sedang berbohong.",answer:false,explain:"Sebaliknya, perbedaan cerita tidak selalu berarti ada yang berbohong. Perhatian, posisi, & kepentingan membentuk apa yang tiap orang tangkap & ingat.",hint:"Beda perhatian, beda ingatan — tanpa bohong."},
{n:39,type:"mcq",micro:"Menahan penilaian",q:"Saat kamu sadar penilaianmu mungkin dipengaruhi bias & informasinya masih sedikit, langkah terbaik:",options:["tahan penilaian sementara, kumpulkan lebih banyak informasi, & minta pandangan orang yang berbeda darimu","segera putuskan sesuai dugaan awal dan jangan menunda-nunda, jadi waktu kelompok tidak terbuang","abaikan bias karena setiap orang memilikinya & tak ada gunanya mencoba melawannya dalam penilaian"],answer:0,explain:"Menahan penilaian & mencari sudut pandang berbeda adalah penawar bias yang paling praktis.",hint:"Tahan, kumpulkan, tanya yang berbeda."},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Alat untuk melawan bias & asumsi tersembunyi:",options:["percaya pada intuisi pertama, mencari bukti yang mendukung, berpegang pada pendapat mayoritas, & mengambil keputusan cepat","menyatakan asumsi dengan jelas, mencari sudut pandang yang hilang, mencari bukti yang melawan dugaan, & melambat saat emosi tinggi","menghindari pendapat yang berbeda, menganggap diri paling objektif dalam kelompok, & tak membahas asumsi dengan anggota lain"],answer:1,explain:"Bias tidak bisa dihapus, tapi bisa dikurangi dengan kebiasaan memeriksa diri yang sederhana & konsisten.",hint:"Nyatakan, cari yang hilang, cari bukti lawan, melambat."},
{n:41,type:"mcq",micro:"Terapan: merencanakan acara",q:"Kelas merencanakan piknik & berkata 'pasti ramai yang ikut & cuacanya cerah'. Asumsi berisiko yang perlu dicek:",options:["warna tenda yang disewa & jenis makanan ringan yang akan dibawa oleh setiap peserta saat tiba di lokasi piknik pada hari Sabtu pagi","piknik itu menyenangkan dan biasanya diikuti oleh teman-teman yang sudah kamu kenal baik","jumlah peserta (lewat pendaftaran) & prakiraan cuaca, plus rencana cadangan bila hujan atau peserta sedikit"],answer:2,explain:"Rencana yang matang mengubah asumsi ('pasti ramai & cerah') menjadi hal yang dicek & disiapkan cadangannya.",hint:"Mana asumsi yang kalau salah, acara berantakan?"},
{n:42,type:"mcq",micro:"Terapan: salah paham karena asumsi",q:"A berkata 'nanti kita ketemu di depan'. A maksudnya depan gerbang, B mengira depan kelas. Akar masalahnya:",options:["keduanya berasumsi 'depan' berarti tempat yang sama tanpa memastikannya","A tidak jelas bicaranya & B memang tidak mendengarkan dengan baik","tempat bertemu terlalu jauh, jadi keduanya tidak menemukan satu sama lain"],answer:0,explain:"Banyak salah paham lahir dari asumsi bahwa kata yang sama berarti hal yang sama bagi kedua pihak. Menyamakan pengertian mencegahnya.",hint:"Kata sama, bayangan berbeda."},
{n:43,type:"mcq",micro:"Terapan: perselisihan & asumsi",q:"Dua teman bertengkar soal 'siapa yang harus minta maaf duluan'. Sering kali di balik ini ada asumsi berbeda tentang...",options:["hari apa pertengkaran itu terjadi & siapa yang lebih dulu sampai di sekolah pada hari itu","siapa yang memulai masalah & apa arti 'minta maaf duluan' (mengaku kalah vs memperbaiki hubungan)","warna baju & merek tas yang dipakai masing-masing sewaktu pertengkaran itu terjadi"],answer:1,explain:"Menemukan asumsi tersembunyi di balik perselisihan (mis. 'minta maaf = mengaku salah total') sering membuka jalan damai.",hint:"Apa yang masing-masing anggap sebagai arti 'minta maaf'?"},
{n:44,type:"open",micro:"Terapan: cek asumsi sebelum menuduh",q:"Kamu menemukan bukumu robek di tas & duduk sebelah Dita hari ini. Kamu berasumsi Dita yang merobeknya. Tuliskan tiga asumsi di balik dugaan itu & cara memeriksanya sebelum berbicara ke Dita.",explain:"Memeriksa asumsi sebelum menuduh melindungi hubungan & mencegah ketidakadilan.",hint:"3 asumsi + cara cek tiap-tiap.",sample:"Asumsi: (1) buku itu masih utuh sebelum aku duduk sebelah Dita — padahal aku belum yakin, bisa jadi sudah robek sejak kemarin; (2) hanya Dita yang menyentuh tasku — padahal tasku sempat kutinggal saat istirahat; (3) robekan itu disengaja — padahal bisa tersangkut ritsleting. Cara mengecek: ingat-ingat kapan terakhir buku itu kubuka & utuh, tanya teman lain apakah ada yang memindahkan tasku, & lihat jenis robekannya. Baru setelah itu aku bicara ke Dita dengan tenang, bukan menuduh."},
{n:45,type:"mcq",micro:"Terapan: sudut pandang guru",q:"Kamu kesal guru memberi PR banyak di akhir pekan. Membayangkan sudut pandang guru bisa berarti...",options:["guru sengaja ingin menyulitkan murid & tak peduli soal istirahat, jadi keberatan sebaiknya disampaikan dengan nada marah","guru tak punya alasan yang masuk akal, jadi PR sebaiknya diabaikan & tak dikerjakan sambil mengajak teman-teman melakukan hal yang sama","guru mungkin mengejar materi yang tertinggal, jadi kamu bisa menyampaikan keberatan dengan sopan sambil mencoba memahami alasannya"],answer:2,explain:"Memahami sudut pandang lain tidak berarti harus setuju; ia membuat percakapan lebih baik & keberatanmu lebih didengar.",hint:"Alasan apa yang mungkin ada di balik keputusan guru?"},
{n:46,type:"order",micro:"Terapan: menilai sebuah keputusan bersama",q:"Urutkan langkah menilai apakah usulan 'melarang semua jajan di kelas' itu adil:",items:["Nyatakan asumsi usulan ini (mis. 'jajan selalu bikin kelas kotor & tidak fokus')","Kumpulkan sudut pandang: murid yang butuh camilan karena alasan kesehatan, petugas kebersihan, guru","Periksa bukti: seberapa besar sebenarnya masalah kebersihan & fokus akibat jajan","Cari opsi tengah (mis. jajan hanya saat istirahat, wajib buang sampah) sebelum melarang total"],answer:[0,1,2,3],explain:"Ungkap asumsi → kumpulkan sudut pandang → periksa bukti → cari jalan tengah.",hint:"Mulai dari menyatakan asumsi usulan."},
{n:47,type:"mcq",micro:"Terapan: bias memihak teman",q:"Dalam sengketa antara sahabatmu & murid lain, kamu ingin adil. Yang membantu:",options:["sadari bahwa kedekatan membuatmu cenderung memihak, lalu sengaja timbang bukti & versi kedua pihak dengan standar yang sama","abaikan perasaanmu & anggap pertengkaran ini urusan mereka berdua, lalu menjauh dan jangan ikut campur dalam masalah mereka","dukung sahabatmu lebih dulu karena persahabatan lebih penting daripada menimbang cerita pihak lain"],answer:0,explain:"Menyadari arah bias kita (memihak yang dekat) adalah syarat untuk mengoreksinya.",hint:"Akui kecenderunganmu, lalu samakan standar."},
{n:48,type:"tf",micro:"Terapan: menyamakan pengertian",q:"Benar atau Salah: Menghabiskan satu-dua menit di awal untuk memastikan semua anggota kelompok memahami tugas dengan cara yang sama adalah pemborosan waktu.",answer:false,explain:"Sebaliknya, menyamakan pengertian di awal biasanya menghemat waktu jauh lebih banyak dengan mencegah pekerjaan yang salah arah.",hint:"Sedikit di depan, hemat banyak di belakang."},
{n:49,type:"mcq",micro:"Terapan: pertanyaan bermuatan asumsi",q:"Seseorang bertanya kepadamu 'Kenapa kamu tidak suka kegiatan olahraga?' padahal kamu tidak pernah bilang begitu. Tanggapan yang baik:",options:["jangan membantah dan hindari pertengkaran; biarkan ia terus mengira begitu tentangmu, walau itu tidak benar","luruskan asumsinya dulu: 'Sebenarnya aku suka olahraga; mungkin kamu melihat aku lelah tadi?'","katakan 'kamu salah, jangan sok tahu tentang aku' dan segera pergi tanpa menjelaskan lagi"],answer:1,explain:"Saat sebuah pertanyaan memuat asumsi keliru, meluruskan asumsinya lebih dulu membuat percakapan kembali ke jalur yang benar.",hint:"Benahi anggapannya sebelum menjawab."},
{n:50,type:"mcq",micro:"Terapan: sudut pandang dalam sejarah & berita",q:"Membaca dua sumber tentang peristiwa yang sama yang menekankan hal berbeda, sikap terbaik:",options:["pilih satu sumber yang kamu sukai & abaikan yang lain; sumber yang berbeda hanya membuatmu bingung","anggap keduanya bohong karena berbeda, lalu cari sumber ketiga yang paling cocok dengan pendapatmu sendiri dan pakai itu sebagai acuan","baca keduanya, perhatikan fakta yang sama-sama disebut, & sadari bahwa tiap sumber menyorot dari sudut pandangnya"],answer:2,explain:"Membandingkan beberapa sudut pandang memberi gambaran yang lebih utuh daripada mengandalkan satu.",hint:"Cari yang sama, sadari yang disorot berbeda."},
{n:51,type:"mcq",micro:"Terapan: asumsi tentang kemampuan orang",q:"Kamu tidak memilih seorang teman untuk tim karena berasumsi 'dia pasti tidak bisa'. Cara yang lebih adil:",options:["beri kesempatan atau tanyakan minat & kemampuannya — asumsi tentang kemampuan orang sering keliru & bisa menutup peluang mereka","coret namanya dari daftar tim; asumsi tentang kemampuan biasanya benar & menghemat waktu, lalu cari saja teman lain yang sudah jelas pandai","tunggu sampai orang lain mengajaknya & jangan berbicara dengannya sebelum itu, sambil berharap ia akan baik-baik saja"],answer:0,explain:"Asumsi tentang siapa yang 'pasti bisa' atau 'pasti tidak bisa' sering salah & tidak adil. Memberi kesempatan menguji asumsi itu.",hint:"Uji asumsimu dengan memberi kesempatan."},
{n:52,type:"open",micro:"Terapan: peta sudut pandang",q:"Sekolah akan mengubah jam masuk menjadi 30 menit lebih pagi. Tuliskan tiga kelompok berbeda yang terdampak & bagaimana perubahan ini mungkin terlihat dari sudut pandang masing-masing.",explain:"Membuat 'peta sudut pandang' sebelum keputusan besar membantu menemukan dampak yang mudah terlewat.",hint:"3 kelompok + sisi masing-masing.",sample:"(1) Murid yang rumahnya jauh & naik angkutan umum: khawatir karena harus berangkat saat masih gelap & angkutan belum banyak. (2) Guru: mungkin menyambut baik karena kegiatan selesai lebih awal, tapi juga perlu menyesuaikan persiapan pagi. (3) Orang tua yang mengantar sambil berangkat kerja: bisa terbantu bila jadwal kerjanya juga pagi, atau justru kesulitan bila harus berangkat lebih awal dari biasanya. Keputusan yang adil menimbang ketiga sisi ini."},
{n:53,type:"mcq",micro:"Terapan: bias berita buruk",q:"Setelah mendengar dua cerita tentang penipuan lewat aplikasi pesan, kamu ingin menolak semua teknologi. Sikap yang lebih seimbang:",options:["hindari seluruh teknologi sejak sekarang; cerita menakutkan lebih bisa dipercaya daripada manfaatnya","kenali bahwa cerita menakutkan terasa besar; timbang juga manfaat & pelajari cara aman memakainya","percaya semua teknologi aman karena cerita penipuan hanya karangan orang yang tak suka kemajuan"],answer:1,explain:"Bias 'yang menakutkan terasa lebih sering' bisa membuat kita bereaksi berlebihan. Menimbang manfaat & risiko secara utuh lebih bijak.",hint:"Timbang manfaat & risiko, jangan hanya rasa takut."},
{n:54,type:"tf",micro:"Terapan: minta pandangan berbeda",q:"Benar atau Salah: Sengaja meminta pendapat orang yang biasanya tidak sepaham denganmu bisa membantu menemukan kelemahan dalam pemikiranmu sendiri.",answer:true,explain:"Orang dengan sudut pandang berbeda sering melihat asumsi & celah yang tak terlihat oleh kita. Ini alat kuat melawan bias.",hint:"Yang berbeda pandangan bisa melihat titik butamu."},
{n:55,type:"mcq",micro:"Terapan: menilai usul sendiri",q:"Kamu sangat menyukai idemu sendiri untuk pentas kelas. Cara menilainya dengan adil:",options:["minta teman sebanyak mungkin memuji idemu, lalu pilih ide itu setelah disetujui banyak orang tanpa pembanding","bandingkan idemu dengan ide lain memakai kriteria yang kamu buat sendiri, & pilih kriteria yang membuat idemu tampak lebih unggul","minta 2-3 teman menyebut kelemahan idemu, & bandingkan jujur dengan ide lain memakai kriteria yang sama"],answer:2,explain:"Rasa memiliki terhadap ide sendiri (bias) membuat kita buta pada kekurangannya. Mengundang kritik & memakai kriteria yang sama menyeimbangkannya.",hint:"Undang kritik atas idemu sendiri."},
{n:56,type:"order",micro:"Terapan: memeriksa kabar yang memancing emosi",q:"Kamu menerima kabar yang membuatmu langsung marah. Urutkan langkahmu:",items:["Sadari emosi kuat ini adalah sinyal untuk melambat","Pisahkan fakta yang benar-benar disebut dari tafsiran & asumsi","Periksa sumber & cari sudut pandang pihak lain","Baru putuskan bagaimana menanggapi, saat kepala lebih dingin"],answer:[0,1,2,3],explain:"Melambat → pisahkan fakta dari asumsi → cek sumber & sisi lain → tanggapi.",hint:"Emosi tinggi → melambat dulu."},
{n:57,type:"mcq",micro:"Terapan: asumsi dalam aturan",q:"Aturan 'dilarang membawa mainan ke sekolah' mungkin berasumsi bahwa...",options:["semua mainan mengganggu belajar — padahal sebagian bisa berguna (mis. untuk terapi sensorik atau kegiatan tertentu), sehingga mungkin perlu pengecualian","mainan hanya dipakai anak kecil untuk bersenang-senang, jadi murid sekolah yang sudah besar tak mungkin membutuhkannya untuk keperluan lain, bahkan untuk terapi","anak-anak membawa mainan hanya untuk pamer kepada temannya, jadi larangan itu adil untuk setiap kasus tanpa kecuali"],answer:0,explain:"Aturan pun bertumpu pada asumsi. Mengenalinya membantu kita mengusulkan perbaikan yang masuk akal, bukan sekadar menolak.",hint:"Apa yang dianggap benar untuk 'semua' kasus?"},
{n:58,type:"mcq",micro:"Terapan: cek diri sebelum posting",q:"Sebelum membagikan komentar keras tentang seseorang secara online, pertanyaan penjaga bias:",options:["'Apakah banyak orang akan setuju dengan komentarku? Apakah komentarku bakal ramai dibicarakan? Apakah aku terlihat berani?'","'Apakah aku sudah tahu sisi ceritanya? Apakah aku akan berkata ini bila ada dia di depanku? Apakah aku sedang sangat emosi?'","'Apakah komentar ini akan membuatku populer? Apakah orang itu pantas dikomentari? Apakah aku sudah kesal dengan dia sejak minggu lalu & ingin membalas?'"],answer:1,explain:"Pertanyaan yang memaksa kita mempertimbangkan sisi lain, tatap muka, & keadaan emosi kita adalah rem yang baik.",hint:"Sisi lain? Berani tatap muka? Sedang emosi?"},
{n:59,type:"tf",micro:"Terapan: memahami ≠ menyetujui",q:"Benar atau Salah: Berusaha memahami sudut pandang seseorang berarti kita otomatis harus setuju dengannya.",answer:false,explain:"Sebaliknya, memahami sudut pandang orang lain adalah langkah untuk menilai lebih adil & berkomunikasi lebih baik — kita tetap boleh tidak setuju setelahnya.",hint:"Paham dulu, setuju atau tidak itu urusan berikutnya."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Dalam keputusan & konflik sehari-hari, kebiasaan yang menjaga keadilan berpikir:",options:["bertindak berdasarkan perasaan pertama, mempercayai kelompok sendiri, menolak pendapat berbeda, & tidak mengubah keputusan","menghindari semua perbedaan pendapat, mengikuti yang paling lantang, dan cepat-cepat menutup pembicaraan","nyatakan asumsi, petakan sudut pandang yang terdampak, sadari arah bias diri sendiri, & melambat saat emosi tinggi"],answer:2,explain:"Empat kebiasaan ini bisa dipakai pada rapat kelas, perselisihan teman, sampai membaca berita.",hint:"Asumsi, sudut pandang, bias diri, melambat."},
{n:61,type:"mcq",micro:"Bias konfirmasi (lanjut)",q:"Kamu yakin 'kelas pagi lebih produktif'. Untuk menguji keyakinan ini tanpa bias konfirmasi, kamu harus...",options:["sengaja mencatat SEMUA hari (pagi & siang) & juga mencari contoh hari pagi yang TIDAK produktif","hanya mencatat hari-hari produktif di kelas pagi, itulah yang membuktikan keyakinanmu kepada teman-temanmu","bertanya kepada teman yang sependapat & mencatat jawaban mereka tanpa memeriksa hari lain"],answer:0,explain:"Melawan bias konfirmasi berarti aktif mencari bukti yang bisa membantah keyakinan kita, bukan hanya yang mendukung.",hint:"Cari juga bukti yang melawan."},
{n:62,type:"mcq",micro:"Salah kira 'semua berpikir sepertiku'",q:"Kamu berasumsi 'semua orang pasti setuju film ini membosankan' karena kamu & dua temanmu berpikir begitu. Kesalahannya:",options:["menganggap pandangan kita salah, hanya tiga orang yang berpikir begitu & orang lain mungkin tak setuju","menganggap pandangan lingkaran kecil kita mewakili semua orang, padahal orang di luar lingkaran itu bisa sangat berbeda","menganggap orang lain tak setuju dengan kita karena kita berpikir berbeda dari kebanyakan orang di sekitar"],answer:1,explain:"Kita cenderung menganggap orang lain berpikir seperti kita ('konsensus palsu'). Lingkaran pertemanan sering mirip pandangannya, sehingga menyesatkan.",hint:"Lingkaranmu bukan semua orang."},
{n:63,type:"tf",micro:"Bias tak bisa dihapus total",q:"Benar atau Salah: Kita tidak bisa menghapus bias sepenuhnya, tetapi kita bisa mengurangi pengaruhnya dengan kebiasaan memeriksa diri & mendengar sudut pandang lain.",answer:true,explain:"Tujuannya bukan 'bebas bias' (tidak mungkin), melainkan 'sadar bias' & punya kebiasaan yang mengoreksinya.",hint:"Kurangi & koreksi, bukan hapus total."},
{n:64,type:"mcq",micro:"Asumsi berlapis",q:"Rencana 'kita jual 100 tiket, dapat untung besar' bertumpu pada beberapa asumsi berlapis. Yang paling berisiko bila salah:",options:["tiket dijual di dekat sekolah & setiap murid membeli satu","panitia mencetak tiket tepat waktu & tak ada yang salah cetak","cukup banyak orang mau & mampu membeli tiket pada harga itu"],answer:2,explain:"Asumsi paling berisiko biasanya yang menentukan seluruh hasil (permintaan pembeli). Itu yang paling perlu diuji lebih dulu, mis. lewat pra-pendaftaran.",hint:"Asumsi mana yang, kalau meleset, seluruh rencana gagal?"},
{n:65,type:"mcq",micro:"Membedakan bias & preferensi",q:"'Aku lebih suka warna biru' vs 'Tim kesukaanku tidak mungkin melakukan pelanggaran'. Perbedaannya:",options:["yang pertama preferensi pribadi yang tidak apa-apa; yang kedua bias yang membuat penilaian tentang fakta jadi tidak adil","keduanya sama-sama preferensi pribadi yang tidak perlu dipertanyakan, dan tim kesukaan memang berhak dibela","keduanya sama-sama bias yang harus dihilangkan karena menyukai warna juga menyebabkan penilaian miring"],answer:0,explain:"Selera pribadi tidak perlu dikoreksi. Bias jadi masalah ketika ia membengkokkan penilaian kita atas fakta atau atas orang.",hint:"Selera vs penilaian fakta yang miring."},
{n:66,type:"open",micro:"Bongkar sebuah keyakinan",q:"Pilih satu keyakinan yang cukup kuat kamu pegang (tentang sekolah, teman, atau kegiatan). Tuliskan: (a) apa asumsi di baliknya, (b) sudut pandang siapa yang mungkin berbeda, (c) bukti apa yang akan membuatmu meninjau ulang keyakinan itu.",explain:"Membongkar keyakinan sendiri secara terstruktur adalah latihan inti berpikir kritis yang matang.",hint:"Asumsi + sudut pandang lain + bukti yang mengubah pikiran.",sample:"Keyakinan: 'Belajar kelompok selalu lebih baik daripada belajar sendiri.' (a) Asumsi: setiap orang belajar lebih baik dengan diskusi, & kelompok selalu fokus. (b) Sudut pandang berbeda: teman yang mudah terganggu keramaian & lebih paham saat membaca sendiri dulu. (c) Bukti yang mengubah pikiranku: kalau nilaiku atau pemahamanku ternyata lebih baik setelah belajar sendiri untuk beberapa topik, atau kalau sesi kelompok sering berubah jadi mengobrol."},
{n:67,type:"mcq",micro:"Efek halo & lawannya",q:"Kamu menganggap tulisan seorang teman pasti bagus karena dia juara kelas, & tulisan teman lain pasti biasa karena nilainya rata-rata. Cara menilai yang lebih adil:",options:["menilai tulisan juara kelas lebih tinggi, ia lebih pintar & tulisan lain tetap dinilai biasa saja","nilai tulisannya sendiri dengan kriteria yang sama, sedapat mungkin tanpa melihat nama penulisnya lebih dulu","menyamakan nilai kedua tulisan tanpa membaca isinya agar tak ada yang merasa dibedakan satu sama lain"],answer:1,explain:"Menilai karya 'buta nama' bila memungkinkan mengurangi efek reputasi (halo) terhadap penilaian.",hint:"Nilai karyanya, bukan reputasi penulisnya."},
{n:68,type:"tf",micro:"Sudut pandang & kebenaran",q:"Benar atau Salah: Karena setiap orang punya sudut pandang, maka semua klaim sama benarnya & tidak ada gunanya mencari fakta.",answer:false,explain:"Sebaliknya, mengakui sudut pandang tidak menghapus fakta. Kita tetap bisa & perlu memeriksa bukti; sudut pandang menjelaskan penekanan, bukan membatalkan kebenaran.",hint:"Sudut pandang ≠ semua benar."},
{n:69,type:"mcq",micro:"Bias status quo",q:"Kelas menolak ide baru hanya karena 'kita selalu melakukannya dengan cara lama'. Ini contoh...",options:["inovasi: kemauan mencoba cara baru walau cara lama sudah dianggap berfungsi dengan baik","kebiasaan baik; cara yang sudah lama dipakai tentu lebih unggul dibanding cara baru","kecenderungan bertahan pada yang sudah biasa tanpa menimbang apakah cara baru sebenarnya lebih baik"],answer:2,explain:"Kenyamanan pada 'yang biasa' adalah bias tersendiri. Cara lama & cara baru sebaiknya dinilai dengan kriteria yang sama.",hint:"'Selalu begitu' bukan alasan bahwa itu terbaik."},
{n:70,type:"order",micro:"Analisis asumsi & bias sebuah klaim",q:"Urutkan langkah memeriksa klaim 'anak yang main game pasti nilainya jelek':",items:["Temukan asumsinya (main game selalu mengurangi waktu & fokus belajar untuk semua orang)","Cari sudut pandang & contoh yang berbeda (anak yang bermain secukupnya & nilainya baik)","Periksa apakah ada bias: apakah kita hanya memperhatikan kasus yang cocok dengan klaim?","Simpulkan dengan hati-hati: hubungannya mungkin ada dalam kondisi tertentu, bukan 'pasti' untuk semua"],answer:[0,1,2,3],explain:"Ungkap asumsi → cari contoh berbeda → periksa bias sendiri → simpulkan dengan hati-hati.",hint:"Mulai dari menemukan asumsi klaim."},
{n:71,type:"tf",micro:"Mengakui salah",q:"Benar atau Salah: Mengubah pendapat setelah menemukan bahwa asumsi kita keliru adalah tanda berpikir yang lemah.",answer:false,explain:"Sebaliknya, itu tanda berpikir yang kuat & jujur. Yang lemah adalah bertahan pada pendapat lama demi gengsi meski buktinya sudah berubah.",hint:"Berubah karena bukti = kuat, bukan lemah."},
{n:72,type:"mcq",micro:"Bias & kelompok mayoritas",q:"Dalam diskusi, pendapat yang paling sering diulang & didukung suara terbanyak...",options:["belum tentu paling benar; pengulangan & jumlah pendukung bukan bukti — pendapat minoritas yang beralasan tetap perlu ditimbang","paling benar, sudah disetujui banyak orang & sering diulang-ulang, jadi tak perlu diperiksa lagi dan pendapat lain boleh diabaikan","salah karena opini yang paling sering diulang biasanya hanya ikut-ikutan & tidak memiliki alasan yang kuat di baliknya selain jumlah suara"],answer:0,explain:"Bias ikut mayoritas membuat kita menyamakan 'populer' dengan 'benar'. Argumen tetap dinilai dari alasan & buktinya.",hint:"Populer ≠ benar."},
{n:73,type:"mcq",micro:"Titik buta",q:"'Titik buta' dalam berpikir adalah...",options:["bagian kelas yang tidak terkena cahaya lampu, jadi sulit dilihat oleh guru maupun murid dari depan","bagian yang tidak bisa kita lihat tentang bias & asumsi kita sendiri, yang justru lebih mudah dilihat orang lain","kelelahan mata akibat terlalu lama menatap layar ponsel atau buku pelajaran setiap hari"],answer:1,explain:"Kita cenderung melihat bias orang lain lebih jelas daripada bias sendiri. Karena itu masukan dari orang lain berharga.",hint:"Bias sendiri yang sulit kita lihat."},
{n:74,type:"open",micro:"Saat sudut pandang mengubah penilaianmu",q:"Ceritakan satu kali mendengar sudut pandang orang lain benar-benar mengubah caramu menilai sebuah situasi. Apa yang baru kamu sadari?",explain:"Sudut pandang baru sering mengungkap asumsi yang tak kita sadari kita pegang.",hint:"Sudut pandang baru + asumsi yang terbongkar.",sample:"Aku dulu kesal pada teman yang sering izin tidak ikut kerja kelompok sore. Aku menganggapnya malas. Setelah mengobrol, aku tahu ia harus menjaga adiknya setiap sore karena orang tuanya bekerja. Aku jadi sadar bahwa aku menilai dari asumsi 'semua orang punya sore yang bebas sepertiku', padahal tidak. Kami lalu mengatur agar ia mengerjakan bagiannya di waktu lain."},
{n:75,type:"mcq",micro:"Kapan bias paling berbahaya",q:"Bias dalam penilaian paling berbahaya ketika...",options:["kita sedang santai dan topiknya ringan, misalnya memilih makanan atau warna favorit bersama teman-teman sekelas","topiknya sepele & tidak berdampak pada orang lain, jadi kita boleh menilai seenaknya","keputusannya berdampak besar pada orang lain (mis. menuduh, mengucilkan, memilih/menolak seseorang) & kita merasa paling yakin"],answer:2,explain:"Rasa yakin yang tinggi + dampak besar pada orang lain adalah kombinasi di mana memeriksa asumsi & bias paling penting.",hint:"Dampak besar + rasa sangat yakin."},
{n:76,type:"tf",micro:"Sudut pandang & data",q:"Benar atau Salah: Mengumpulkan data dari banyak sudut pandang yang berbeda cenderung memberi gambaran yang lebih akurat daripada mengandalkan satu sudut pandang saja.",answer:true,explain:"Beberapa sudut pandang saling menambal titik buta. Ini prinsip yang dipakai dari jurnalisme sampai penelitian.",hint:"Banyak sudut pandang menutup titik buta."},
{n:77,type:"mcq",micro:"Bias & bahasa",q:"Menyebut kelompok yang tidak setuju dengan kita sebagai 'orang-orang bodoh' membuat kita...",options:["berhenti mendengarkan & kehilangan kesempatan menemukan kelemahan pikiran kita sendiri","merasa lebih pintar & tak perlu lagi memeriksa pendapat sendiri dengan teliti","lebih mudah memahami alasan mereka & mendapat teman baru dari kelompok itu"],answer:0,explain:"Merendahkan pihak lain memuaskan sesaat tetapi menutup pintu belajar. Argumen mereka mungkin memuat poin yang kita lewatkan.",hint:"Meremehkan = berhenti belajar."},
{n:78,type:"mcq",micro:"Memeriksa asumsi ahli",q:"Bahkan penjelasan dari orang yang ahli sebaiknya kita...",options:["terima begitu saja; ia ahli & tak mungkin keliru dalam bidang yang ia pelajari bertahun-tahun","pahami dasarnya: bukti & asumsi apa yang ia pakai, & apakah ada ahli lain yang berbeda pandangan","tolak begitu saja karena ahli biasanya dibayar untuk berkata sesuatu & tak layak dipercaya oleh orang awam"],answer:1,explain:"Menghormati keahlian tidak berarti berhenti berpikir. Memahami dasar sebuah penjelasan membuat kita belajar, bukan sekadar percaya.",hint:"Hormati keahlian, tetap pahami dasarnya."},
{n:79,type:"tf",micro:"Emosi & berpikir",q:"Benar atau Salah: Emosi tidak selalu musuh berpikir jernih; emosi bisa memberi tahu kita bahwa sesuatu penting, asalkan kita tidak membiarkannya menutup pertimbangan.",answer:true,explain:"Tujuannya bukan membuang emosi, melainkan menyadarinya & tidak membiarkannya menjadi satu-satunya penentu penilaian.",hint:"Emosi sebagai isyarat, bukan hakim tunggal."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Cara paling praktis mengurangi pengaruh bias pada dirimu:",options:["percayai intuisi pertama, cari bukti yang mendukung dugaanmu, ikuti pendapat mayoritas, & percepat keputusan terutama saat kamu sedang sangat yakin dan emosional","hindari orang yang berbeda pendapat, nilai karya berdasarkan nama pembuatnya, & berpegang teguh pada pilihanmu semula walau muncul bukti baru kemudian","bangun kebiasaan: cari bukti yang melawan, undang sudut pandang berbeda, nilai karya tanpa melihat nama bila bisa, & melambat saat sangat yakin atau sangat emosi"],answer:2,explain:"Bias tidak kalah oleh niat, melainkan oleh kebiasaan & prosedur kecil yang konsisten.",hint:"Kebiasaan konkret, bukan sekadar niat."},
{n:81,type:"mcq",micro:"Analisis keputusan lengkap",q:"Kelas akan memilih satu perwakilan lomba cerdas cermat. Analisis berpikir kritis yang lengkap mempertimbangkan:",options:["asumsi ('yang nilainya tinggi pasti paling cocok'), sudut pandang (yang belum pernah diberi kesempatan), bukti (hasil latihan, bukan kesan), & bias (memihak teman dekat)","pilih yang nilainya tertinggi; itu paling objektif, jadi asumsi, sudut pandang, bukti, & bias tak perlu dipertimbangkan lagi dalam keputusan","pilih yang paling populer di kelas karena didukung banyak teman, lomba akan lebih seru, & hasil latihan para calon tak perlu diperiksa terlebih dahulu"],answer:0,explain:"Keputusan yang adil menyatukan pemeriksaan asumsi, sudut pandang, bukti, & kesadaran bias.",hint:"Asumsi + sudut pandang + bukti + bias."},
{n:82,type:"open",micro:"Analisis klaim menyeluruh",q:"Ambil klaim: 'Murid zaman sekarang kurang sopan dibanding dulu.' Tuliskan: (a) 2 asumsi di baliknya, (b) sudut pandang siapa yang mungkin berbeda, (c) 1 bias yang mungkin memengaruhi orang yang mengucapkannya, (d) bukti apa yang dibutuhkan untuk menilainya adil.",explain:"Klaim perbandingan antar zaman sangat rawan asumsi tak terucap & bias ingatan. Analisis menyeluruh membongkarnya.",hint:"Asumsi + sudut pandang + bias + bukti yang dibutuhkan.",sample:"(a) Asumsi: 'sopan' berarti hal yang sama di setiap zaman; & ingatan tentang 'dulu' akurat. (b) Sudut pandang berbeda: murid sekarang mungkin menunjukkan hormat dengan cara lain; guru muda mungkin melihatnya berbeda dari guru senior. (c) Bias: orang cenderung mengingat masa mudanya lebih indah & lebih mengingat kejadian buruk yang baru terjadi. (d) Bukti: perbandingan yang jelas & terukur (mis. catatan pelanggaran per murid) antar periode dengan definisi 'sopan' yang sama, bukan sekadar kesan."},
{n:83,type:"mcq",micro:"Asumsi yang saling bertabrakan",q:"Dua kelompok berdebat sengit soal 'apakah HP boleh dibawa ke sekolah'. Sering kali akar debatnya adalah...",options:["satu kelompok sengaja berniat jahat & ingin mengganggu kenyamanan kelompok lain dengan membawa HP ke kelas di sekolah setiap hari","asumsi berbeda tentang tujuan sekolah, tingkat tanggung jawab murid, & apa risiko terbesarnya — memunculkan asumsi ini bisa membuat debat lebih produktif","perbedaan merek & warna HP yang dimiliki masing-masing kelompok, yang membuat mereka sulit sepakat satu sama lain dalam urusan sekolah"],answer:1,explain:"Debat yang buntu sering karena asumsi dasar yang tak diucapkan berbeda. Menyingkap asumsi mengubah 'bertengkar' menjadi 'membahas'.",hint:"Cari asumsi dasar yang berbeda di kedua pihak."},
{n:84,type:"tf",micro:"Berpikir kritis pada diri sendiri",q:"Benar atau Salah: Bagian tersulit sekaligus terpenting dari berpikir kritis adalah menerapkannya pada pikiran & keyakinan kita sendiri, bukan hanya pada pikiran orang lain.",answer:true,explain:"Mudah melihat kelemahan argumen orang lain; jauh lebih sulit & lebih berharga memeriksa asumsi & bias diri sendiri.",hint:"Arahkan ke dalam, bukan hanya ke luar."},
{n:85,type:"mcq",micro:"Sudut pandang & keadilan aturan",q:"Sebuah aturan tampak 'adil untuk semua' bagi yang membuatnya, tetapi memberatkan sekelompok kecil murid. Sikap berpikir kritis:",options:["pertahankan aturan; sudah adil menurut pembuatnya, & kelompok kecil itu harus menyesuaikan diri tanpa perlu didengar keberatannya","hapus aturan itu seluruhnya karena aturan yang memberatkan satu kelompok tak boleh ada, tanpa menimbang manfaatnya bagi yang lain","perlakuan yang sama belum tentu adil bila titik awal orang berbeda; dengarkan kelompok yang terbebani & pertimbangkan penyesuaian"],answer:2,explain:"Keadilan sering menuntut mempertimbangkan sudut pandang & keadaan yang berbeda, bukan hanya menerapkan aturan seragam.",hint:"Sama ≠ selalu adil."},
{n:86,type:"order",micro:"Toolkit berpikir kritis",q:"Urutkan alur memakai seluruh keterampilan berpikir kritis pada sebuah situasi baru:",items:["Amati dengan teliti & pisahkan pengamatan dari tafsiran","Bandingkan & kelompokkan: apa yang mirip, apa yang berbeda, pola apa yang muncul","Tarik kesimpulan sementara dari petunjuk, sadari itu bisa keliru","Pilah fakta, opini, & klaim; telusuri sebab-akibat bila relevan","Periksa asumsi, sudut pandang yang hilang, & bias diri sendiri","Simpulkan dengan keyakinan yang sepadan bukti, & tetap terbuka pada informasi baru"],answer:[0,1,2,3,4,5],explain:"Observasi → perbandingan/pola → inferensi → fakta-opini & sebab-akibat → asumsi/sudut pandang/bias → kesimpulan yang bisa direvisi. Semua keterampilan CT bekerja bersama.",hint:"Mengamati dulu, menyimpulkan dengan rendah hati terakhir."},
{n:87,type:"mcq",micro:"Menggabungkan alat",q:"Saat menilai pesan berantai yang menakutkan tentang suatu kelompok orang, keterampilan CT yang perlu dipakai bersama:",options:["pisahkan fakta dari klaim, periksa sumber, sadari bias 'kami vs mereka', pikirkan sudut pandang kelompok yang dibicarakan, & telusuri apakah sebab-akibat yang disebut masuk akal","sebarkan pesan ke teman-teman supaya semua waspada, lalu tunggu penjelasan dari orang yang lebih tahu tanpa memeriksa sumber atau fakta dalam pesan itu terlebih dahulu","percayai pesan itu karena terdengar meyakinkan & banyak yang membagikannya, tanpa memeriksa siapa pembuatnya, apa buktinya, atau bagaimana kelompok itu sendiri memandangnya"],answer:0,explain:"Situasi nyata jarang butuh satu keterampilan saja; berpikir kritis adalah memakai beberapa alat sekaligus.",hint:"Fakta/klaim + sumber + bias kelompok + sudut pandang + sebab-akibat."},
{n:88,type:"open",micro:"Rancang pemeriksaan",q:"Kamu akan mengambil sebuah keputusan cukup penting minggu ini (mis. memilih ekstrakurikuler, atau menanggapi konflik dengan teman). Tuliskan 4-5 pertanyaan pemeriksaan yang akan kamu ajukan pada diri sendiri sebelum memutuskan.",explain:"Daftar pemeriksaan pribadi mengubah keterampilan berpikir kritis menjadi kebiasaan yang benar-benar dipakai saat penting.",hint:"4-5 pertanyaan: fakta, asumsi, sudut pandang, bias, risiko.",sample:"1) Fakta apa yang benar-benar kutahu, & mana yang baru dugaan? 2) Asumsi apa yang kubuat tentang orang atau situasi ini, & bisakah kuperiksa? 3) Sudut pandang siapa yang belum kupertimbangkan? 4) Apakah penilaianku dipengaruhi bias — memihak teman, kesan pertama, atau keinginan agar sesuatu benar? 5) Kalau aku salah, seberapa besar dampaknya, & apa yang bisa kucek dulu untuk mengurangi risiko itu?"},
{n:89,type:"mcq",micro:"Batas berpikir kritis",q:"Berpikir kritis TIDAK berarti...",options:["percaya pada pendapat orang yang paling meyakinkan & menerima sebagian besar informasi yang kamu terima","menolak & mencurigai segalanya, termasuk hal yang sudah didukung bukti kuat & kesepakatan para ahli","membandingkan beberapa sumber & mengakui bahwa kamu belum tahu semua jawaban dengan jujur"],answer:1,explain:"Berpikir kritis adalah menimbang secara adil — percaya yang terdukung kuat, meragukan yang lemah — bukan sinisme yang menolak semua.",hint:"Menimbang, bukan menolak semua."},
{n:90,type:"tf",micro:"Kerendahan hati intelektual",q:"Benar atau Salah: Orang yang berpikir kritis dengan baik biasanya bersedia mengatakan 'aku bisa saja keliru' & 'aku belum tahu pasti'.",answer:true,explain:"Kerendahan hati intelektual — mengakui batas pengetahuan sendiri — adalah ciri khas pemikir yang matang, bukan tanda kelemahan.",hint:"'Aku bisa keliru' = kekuatan."},
{n:91,type:"mcq",micro:"Sudut pandang & cerita sejarah",q:"Sebuah peristiwa sejarah diceritakan berbeda oleh dua bangsa yang terlibat. Pemikir kritis akan...",options:["memilih versi bangsa sendiri, itu yang paling dikenal sejak kecil & menganggap versi bangsa lain bohong atau dibuat-buat","menganggap kedua versi sama-sama salah & tak mempelajari sejarah itu agar tak dianggap memihak salah satu pihak yang terlibat dalam peristiwa","mencari fakta yang disepakati kedua sumber, memahami mengapa penekanannya berbeda, & mencari sumber ketiga yang lebih netral bila ada"],answer:2,explain:"Perbedaan narasi sering mencerminkan sudut pandang & kepentingan, bukan sekadar kebohongan. Fakta inti biasanya masih bisa ditemukan.",hint:"Cari yang disepakati, pahami perbedaan penekanan."},
{n:92,type:"mcq",micro:"Bias dalam menilai diri sendiri",q:"Banyak orang menilai dirinya 'lebih adil & lebih objektif dari rata-rata'. Ini menunjukkan...",options:["kita punya titik buta terhadap bias kita sendiri — termasuk bias merasa tidak bias","kita memang lebih objektif daripada orang lain, sudah belajar berpikir kritis di sekolah","orang lain tidak memiliki bias sehingga hanya kita yang perlu memeriksa penilaian dengan hati-hati"],answer:0,explain:"Justru keyakinan 'aku sih objektif' bisa membuat kita berhenti memeriksa diri. Menganggap diri mungkin bias adalah titik awal yang lebih sehat.",hint:"Merasa 'tidak bias' itu sendiri bisa jadi bias."},
{n:93,type:"open",micro:"Refleksi keterampilan CT",q:"Setelah mempelajari observasi, perbandingan, klasifikasi, pola, inferensi, fakta-opini, sebab-akibat, & asumsi-bias — tuliskan keterampilan mana yang menurutmu paling sering kamu butuhkan sehari-hari & mengapa.",explain:"Merefleksikan keterampilan mana yang paling relevan bagi hidupmu sendiri membuat latihan ini bermakna & melekat.",hint:"Pilih 1-2 keterampilan + alasan dari hidupmu.",sample:"Menurutku memisahkan fakta dari opini/klaim & memeriksa asumsi adalah yang paling sering kubutuhkan, karena setiap hari aku menerima banyak pesan, cerita teman, & konten online yang bercampur antara yang benar-benar terjadi & yang hanya pendapat atau dugaan. Kalau aku tidak memilahnya, aku mudah ikut marah, ikut percaya, atau menilai orang dengan tidak adil."},
{n:94,type:"mcq",micro:"Menerapkan pada informasi yang kamu suka",q:"Ujian sejati berpikir kritis adalah ketika kamu memeriksa dengan sama telitinya...",options:["informasi dari teman dekatmu sekeras kamu memeriksa informasi dari orang asing","informasi yang mendukung pendapatmu sekeras kamu memeriksa yang melawannya","informasi yang sudah banyak dibagikan sekeras kamu memeriksa informasi temuanmu sendiri"],answer:1,explain:"Mudah bersikap kritis pada hal yang tidak kita sukai. Kematangan terlihat saat kita menerapkan standar yang sama pada hal yang kita ingin percaya.",hint:"Periksa yang kamu sukai sekeras yang tidak."},
{n:95,type:"tf",micro:"Tujuan akhir",q:"Benar atau Salah: Tujuan berpikir kritis adalah agar kita lebih akurat memahami kenyataan & lebih adil pada orang lain, bukan sekadar memenangkan argumen.",answer:true,explain:"Berpikir kritis yang baik membuat pemahaman kita lebih dekat pada kebenaran & perlakuan kita pada orang lain lebih adil.",hint:"Akurat & adil, bukan menang."},
{n:96,type:"mcq",micro:"Menghadapi ketidakpastian",q:"Setelah memeriksa asumsi, sudut pandang, & bukti, kamu masih belum yakin. Sikap yang matang:",options:["pura-pura yakin sepenuhnya, terlihat tegas & orang lain percaya tanpa banyak bertanya, lalu pertahankan pendapat itu walau ada bukti baru","hindari memberi pendapat sampai kamu benar-benar yakin 100% dan tak seorang pun bisa membantahnya, berapa lama pun kamu harus menunggu","nyatakan tingkat keyakinanmu secara jujur ('aku condong ke A, tapi belum yakin'), sebutkan apa yang masih perlu diketahui, & bersedia berubah"],answer:2,explain:"Berpikir kritis mengizinkan kesimpulan bertingkat: dari 'sangat yakin' sampai 'masih terbuka'. Kejujuran tentang tingkat keyakinan adalah bagian dari keterampilan ini.",hint:"Nyatakan keyakinan bertingkat, bukan yakin penuh atau menyerah."},
{n:97,type:"mcq",micro:"Kesimpulan paling matang",q:"Di antara pernyataan ini, mana yang paling mencerminkan berpikir kritis yang baik?",options:["'Berdasarkan bukti yang kupunya sekarang, aku condong ke pandangan ini; aku sudah pertimbangkan sudut pandang lain & sadar biasku; aku akan tinjau ulang bila ada informasi baru.'","'Aku yakin ini benar; aku sudah memikirkannya lama & seluruh kelas ini setuju denganku, jadi aku tak perlu memeriksa lagi walau nanti muncul informasi baru.'","'Aku tak perlu menimbang pandangan lain, karena bukti milikku sudah kuat dan lengkap, dan perasaanku juga mengatakan bahwa aku benar sepenuhnya dalam hal ini.'"],answer:0,explain:"Kesimpulan yang matang menyebut dasar bukti, mengakui sudut pandang lain & bias, & tetap terbuka pada revisi.",hint:"Berdasar bukti + sadar bias + terbuka direvisi."},
{n:98,type:"order",micro:"Menanggapi tuduhan terhadap teman",q:"Beredar tuduhan bahwa temanmu mencontek. Urutkan langkah berpikir kritismu:",items:["Pisahkan fakta yang benar-benar ada dari desas-desus & tafsiran","Periksa asumsi ('nilai naik drastis = pasti mencontek') & cari penjelasan lain","Sadari biasmu (memihak atau justru sudah lama tak suka padanya) & sudut pandang yang belum terdengar","Tahan penilaian sampai bukti cukup; dukung proses yang adil, jangan sebarkan tuduhan"],answer:[0,1,2,3],explain:"Fakta vs desas-desus → periksa asumsi & alternatif → sadari bias & sudut pandang → tahan penilaian & dukung keadilan.",hint:"Fakta dulu, keadilan proses terakhir."},
{n:99,type:"open",micro:"Janji berpikir",q:"Tuliskan 'janji berpikir' pribadimu: 2-3 kalimat tentang bagaimana kamu ingin memperlakukan informasi & pendapat orang lain mulai sekarang.",explain:"Menuliskan komitmen dengan kata sendiri membuat keterampilan ini menjadi bagian dari cara hidup, bukan sekadar materi pelajaran.",hint:"2-3 kalimat komitmen, dengan katamu sendiri.",sample:"Aku berjanji memeriksa apakah sesuatu itu fakta, opini, atau dugaan sebelum mempercayainya atau menyebarkannya. Aku akan mencoba memahami sudut pandang orang lain sebelum menilai, & memeriksa pendapatku sendiri sekeras aku memeriksa pendapat orang lain. Kalau aku keliru, aku akan berani mengubah pikiran."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan",q:"Inti seluruh keterampilan berpikir kritis adalah...",options:["membuat kesimpulan cepat dari kesan pertama, setuju dengan pendapat yang banyak dipegang orang, & mempertahankannya dengan keyakinan penuh walau muncul bukti baru yang bertentangan dengannya","mengamati dengan teliti, membedakan jenis pernyataan & menimbang bukti, memeriksa asumsi & sudut pandang, mengenali bias diri, lalu menyimpulkan dengan keyakinan yang sepadan bukti & tetap terbuka diperbaiki","menolak setiap klaim dan informasi dari orang lain, memeriksa semuanya sendiri tanpa bantuan orang lain, & jarang menyimpulkan, takut keliru suatu saat nanti"],answer:1,explain:"Berpikir kritis adalah kebiasaan menilai dunia secara akurat & adil: menuntut bukti pada tempatnya, mengenali batas diri, & bersedia belajar.",hint:"Amati, timbang bukti, periksa asumsi & bias, simpulkan dengan rendah hati."},
];
